import os
import json
import subprocess
import logging
from urllib.parse import unquote

logger = logging.getLogger()
logger.setLevel(logging.INFO)

def sanitize_filename(filename):
    """Basic sanitization - remove path traversal attempts"""
    filename = filename.replace('..', '').replace('/', '').replace('\\', '')
    return filename

def get_file_metadata(filename):
    """Get file metadata using system exiftool for comprehensive analysis"""
    safe_name = sanitize_filename(filename)
    upload_dir = os.environ.get('UPLOAD_DIR', '/tmp/uploads')
    filepath = os.path.join(upload_dir, safe_name)

    # Use exiftool for metadata extraction - supports many formats
    cmd = f"exiftool -json {filepath}"
    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=30
        )
        if result.returncode == 0:
            return json.loads(result.stdout)
        else:
            return {"error": result.stderr}
    except subprocess.TimeoutExpired:
        return {"error": "timeout"}
    except Exception as e:
        return {"error": str(e)}

def process_batch_request(filenames):
    """Process multiple files for metadata extraction"""
    results = []
    for fname in filenames:
        meta = get_file_metadata(fname)
        results.append({"filename": fname, "metadata": meta})
    return results

def handler(event, context):
    """Lambda function handler for file metadata service.

    Deployed as ECS Fargate task with Lambda runtime interface.
    Accepts requests via Function URL.
    """
    logger.info(f"Received event: {json.dumps(event)}")

    try:
        http_method = event.get('requestContext', {}).get('http', {}).get('method', 'GET')

        if http_method == 'GET':
            # Single file metadata request
            params = event.get('queryStringParameters', {}) or {}
            filename = params.get('file', '')

            if not filename:
                return {
                    'statusCode': 400,
                    'body': json.dumps({'error': 'file parameter required'})
                }

            filename = unquote(filename)
            metadata = get_file_metadata(filename)

            return {
                'statusCode': 200,
                'headers': {'Content-Type': 'application/json'},
                'body': json.dumps({'result': metadata})
            }

        elif http_method == 'POST':
            # Batch metadata request
            body = json.loads(event.get('body', '{}'))
            filenames = body.get('files', [])

            if not filenames or len(filenames) > 20:
                return {
                    'statusCode': 400,
                    'body': json.dumps({'error': 'provide 1-20 filenames'})
                }

            results = process_batch_request(filenames)

            return {
                'statusCode': 200,
                'headers': {'Content-Type': 'application/json'},
                'body': json.dumps({'results': results})
            }

        else:
            return {
                'statusCode': 405,
                'body': json.dumps({'error': 'method not allowed'})
            }

    except Exception as e:
        logger.error(f"Error processing request: {str(e)}")
        return {
            'statusCode': 500,
            'body': json.dumps({'error': 'internal server error'})
        }
